import 'dart:async';
import 'dart:math';
import 'package:flutter/material.dart';
import 'package:shared_preferences/shared_preferences.dart';

void main() async {
  WidgetsFlutterBinding.ensureInitialized();
  final prefs = await SharedPreferences.getInstance();
  runApp(YeHidnistApp(prefs: prefs));
}

class AppState extends ChangeNotifier {
  AppState(this.prefs) {
    dark = prefs.getBool('dark') ?? false;
    name = prefs.getString('name') ?? 'Олексій Коваль';
    role = prefs.getString('role') ?? 'Учень';
    school = prefs.getString('school') ?? 'Ліцей №1';
    logged = prefs.getBool('logged') ?? false;
    messages = List<String>.from(prefs.getStringList('messages') ?? const []);
  }
  final SharedPreferences prefs;
  bool dark = false, logged = false;
  String name = '', role = '', school = '';
  List<String> messages = [];
  void setDark(bool v) { dark = v; prefs.setBool('dark', v); notifyListeners(); }
  void login(String n, String r, String s) { name=n; role=r; school=s; logged=true; prefs..setString('name',n)..setString('role',r)..setString('school',s)..setBool('logged',true); notifyListeners(); }
  void logout() { logged=false; prefs.setBool('logged',false); notifyListeners(); }
  void addMessage(String text) { messages=[...messages,text]; prefs.setStringList('messages', messages); notifyListeners(); }
}

class YeHidnistApp extends StatelessWidget {
  const YeHidnistApp({super.key, required this.prefs});
  final SharedPreferences prefs;
  @override Widget build(BuildContext context) => Root(prefs:prefs);
}

class Root extends StatefulWidget { const Root({super.key, required this.prefs}); final SharedPreferences prefs; @override State<Root> createState()=>_RootState(); }
class _RootState extends State<Root> {
  late final AppState state;
  @override void initState(){super.initState(); state=AppState(widget.prefs); state.addListener(_changed);}
  void _changed()=>setState((){});
  @override void dispose(){state.removeListener(_changed);state.dispose();super.dispose();}
  @override Widget build(BuildContext context)=>MaterialApp(
    debugShowCheckedModeBanner:false, title:'Є-Гідність', themeMode:state.dark?ThemeMode.dark:ThemeMode.light,
    theme:buildTheme(false), darkTheme:buildTheme(true), home: state.logged ? Shell(state:state) : Access(state:state));
}

ThemeData buildTheme(bool dark){
  final seed=const Color(0xFF1769D2); final cs=ColorScheme.fromSeed(seedColor:seed,brightness:dark?Brightness.dark:Brightness.light);
  return ThemeData(useMaterial3:true,colorScheme:cs,brightness:dark?Brightness.dark:Brightness.light,scaffoldBackgroundColor:dark?const Color(0xFF08111D):const Color(0xFFF4F7FB),fontFamily:'sans',
    appBarTheme:const AppBarTheme(centerTitle:false,elevation:0), cardTheme:CardThemeData(elevation:0,margin:EdgeInsets.zero,shape:RoundedRectangleBorder(borderRadius:BorderRadius.all(Radius.circular(20)))),
    inputDecorationTheme:InputDecorationTheme(filled:true,fillColor:dark?const Color(0xFF101D2C):Colors.white,border:OutlineInputBorder(borderRadius:BorderRadius.all(Radius.circular(16)),borderSide:BorderSide.none),contentPadding:const EdgeInsets.symmetric(horizontal:16,vertical:15)),
  );
}

