class QrDialog extends StatefulWidget{const QrDialog({super.key});@override State<QrDialog>createState()=>_QrState();}class _QrState extends State<QrDialog>{late Timer timer;int seconds=300;@override void initState(){super.initState();timer=Timer.periodic(const Duration(seconds:1),(_){if(mounted)setState(()=>seconds=max(0,seconds-1));});}@override void dispose(){timer.cancel();super.dispose();}@override Widget build(BuildContext c)=>AlertDialog(title:const Text('Мій QR-код'),content:Column(mainAxisSize:MainAxisSize.min,children:[const QrVisual(),const SizedBox(height:12),Text('Дійсний ще ${seconds~/60}:${(seconds%60).toString().padLeft(2,'0')}'),const SizedBox(height:8),const Text('Покажіть код педагогові для демонстраційного підключення.',textAlign:TextAlign.center,style:TextStyle(fontSize:12))]));}
class ScanDialog extends StatefulWidget{const ScanDialog({super.key});@override State<ScanDialog>createState()=>_ScanDialogState();}class _ScanDialogState extends State<ScanDialog>{int step=0;@override Widget build(BuildContext c)=>AlertDialog(title:const Text('Сканування QR'),content:Column(mainAxisSize:MainAxisSize.min,children:[Container(width:230,height:230,decoration:BoxDecoration(border:Border.all(color:Theme.of(c).colorScheme.primary,width:3),borderRadius:BorderRadius.circular(24)),child:Icon(step==0?Icons.qr_code_scanner:Icons.check_circle,size:80,color:Theme.of(c).colorScheme.primary)),const SizedBox(height:15),Text(step==0?'Наведіть камеру на QR-код':'Знайдено: Дмитро • 8-Б'),const SizedBox(height:14),FilledButton(onPressed:()=>setState(()=>step=1-step),child:Text(step==0?'Імітувати сканування':'Готово'))]));}
class QrVisual extends StatelessWidget{const QrVisual({super.key});@override Widget build(BuildContext c)=>Container(width:230,height:230,padding:14,color:Colors.white,child:CustomPaint(painter:QrPainter()));}class QrPainter extends CustomPainter{@override void paint(Canvas canvas,Size size){final p=Paint()..color=Colors.black;final r=Random(42);final n=25;final cell=size.width/n;for(int y=0;y<n;y++){for(int x=0;x<n;x++){if(r.nextDouble()>.53)canvas.drawRect(Rect.fromLTWH(x*cell,y*cell,cell-.5,cell-.5),p);}}for(final o in [Offset(1,1),Offset(n-8,1),Offset(1,n-8)]){canvas.drawRect(Rect.fromLTWH(o.dx*cell,o.dy*cell,7*cell,7*cell),p..color=Colors.black);canvas.drawRect(Rect.fromLTWH((o.dx+1)*cell,(o.dy+1)*cell,5*cell,5*cell),p..color=Colors.white);canvas.drawRect(Rect.fromLTWH((o.dx+2)*cell,(o.dy+2)*cell,3*cell,3*cell),p..color=Colors.black);}}@override bool shouldRepaint(covariant CustomPainter oldDelegate)=>false;}

class AdminPage extends StatefulWidget{const AdminPage({super.key,required this.state});final AppState state;@override State<AdminPage>createState()=>_AdminPageState();}
class _AdminPageState extends State<AdminPage>{int tab=0;final tabs=['Огляд','Користувачі','Класи','Новини','Модерація','Скарги','Журнал'];@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Адмін-панель'),actions:[IconButton(onPressed:()=>widget.state.setDark(!widget.state.dark),icon:Icon(widget.state.dark?Icons.light_mode:Icons.dark_mode))]),body:Column(children:[SingleChildScrollView(scrollDirection:Axis.horizontal,padding:const EdgeInsets.all(12),child:Row(children:List.generate(tabs.length,(i)=>Padding(padding:const EdgeInsets.only(right:7),child:ChoiceChip(label:Text(tabs[i]),selected:tab==i,onSelected:(_)=>setState(()=>tab=i)))))),Expanded(child:tab==0?_AdminOverview():ListView.builder(padding:const EdgeInsets.all(16),itemCount:tab==1?18:tab==2?7:tab==3?6:tab==4?8:tab==5?6:25,itemBuilder:(c,i)=>Card(child:ListTile(leading:CircleAvatar(child:Text('${i+1}')),title:Text('${tabs[tab]} • запис №${i+1}'),subtitle:const Text('Демонстраційний запис • локальне збереження'),trailing:const Icon(Icons.chevron_right)))))]));}}
class _AdminOverview extends StatelessWidget{@override Widget build(BuildContext c){final data=[('Користувачі','1 248',Icons.people),('Класи','42',Icons.class_),('Чати','86',Icons.chat),('Повідомлення','12 490',Icons.forum),('Новини','126',Icons.newspaper),('Скарги','8',Icons.report_problem)];return GridView.builder(padding:const EdgeInsets.all(16),gridDelegate:SliverGridDelegateWithFixedCrossAxisCount(crossAxisCount:MediaQuery.sizeOf(c).width>900?3:2,crossAxisSpacing:12,mainAxisSpacing:12,childAspectRatio:1.45),itemCount:data.length,itemBuilder:(c,i){final d=data[i];return Card(child:Padding(padding:const EdgeInsets.all(18),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Icon(d.$3,color:Theme.of(c).colorScheme.primary,size:28),const Spacer(),Text(d.$2,style:const TextStyle(fontSize:27,fontWeight:FontWeight.w900)),Text(d.$1,style:Theme.of(c).textTheme.bodySmall)])));});}}

